import { existsSync, readdirSync } from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';

const distDir = path.resolve(__dirname, '../../dist');
const pagefindDir = path.join(distDir, 'pagefind');
// dist/pagefind/ is generated by `pnpm build` (postbuild pagefind step) and
// is gitignored. The three assertions below skip when the directory is
// absent — local runs after a build verify the output, CI without a build
// step skips quietly. Run `pnpm build` then `pnpm vitest run tests/build/pagefind-index.test.ts`
// to exercise these locally.
const PAGEFIND_PRESENT = existsSync(pagefindDir);

describe('pagefind build output', () => {
  it.skipIf(!PAGEFIND_PRESENT)('dist/pagefind/ directory exists', () => {
    expect(existsSync(pagefindDir)).toBe(true);
  });

  it.skipIf(!PAGEFIND_PRESENT)('contains pagefind.js entry point', () => {
    expect(existsSync(path.join(pagefindDir, 'pagefind.js'))).toBe(true);
  });

  it.skipIf(!PAGEFIND_PRESENT)('contains at least one index chunk', () => {
    const files = readdirSync(pagefindDir);
    const hasChunk = files.some((f) => f.endsWith('.pf_meta'));
    expect(hasChunk).toBe(true);
  });
});
